        self.assertEqual(run(['3', '1', '2']), {'n': 2, 'mean': 6.5, 'max': 7, 'ratio': 0.667})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'mean': 12.5, 'max': 14, 'ratio': 0.667})
