        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'mean': 10.5, 'max': 12, 'ratio': 0.667})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'ratio': 0.0})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'mean': 16.0, 'max': 16, 'ratio': 0.667})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'mean': 0.0, 'max': 0, 'ratio': 0.0})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 10.0, 'max': 10, 'ratio': 1.333})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'mean': 25.0, 'max': 44, 'ratio': 0.667})

